import { findNeighbours } from "../helper";
export function PlayerFactory() {
    const availableMoves = [
        ...Array.from({ length: 10 }, (_, x) => Array.from({ length: 10 }, (_, y) => `${x + 1},${y + 1}`)).flat(),
    ];
    let lastHitCoord = null;
    const attack = (board, target) => {
        if (!availableMoves.includes(target))
            return "That move is not available";
        board.receiveAttack(target);
        const index = availableMoves.indexOf(target);
        if (index > -1)
            availableMoves.splice(index, 1);
    };
    const randomMove = (board) => {
        const randomTarget = availableMoves[Math.floor(Math.random() * availableMoves.length)];
        attack(board, randomTarget);
        return randomTarget;
    };
    const computerMove = (board) => {
        if (lastHitCoord === null) {
            // Pick a random square
            const target = randomMove(board);
            if (board.hits.includes(target)) {
                lastHitCoord = target;
            }
            return target;
        }
        else {
            const [xStr, yStr] = lastHitCoord.split(",");
            const x = parseInt(xStr, 10);
            const y = parseInt(yStr, 10);
            const neighbours = findNeighbours(x, y);
            const possibleCoords = [
                neighbours.right,
                neighbours.left,
                neighbours.top,
                neighbours.bottom,
            ].filter((c) => !!c && availableMoves.includes(c));
            if (possibleCoords.length > 0) {
                const target = possibleCoords[Math.floor(Math.random() * possibleCoords.length)];
                attack(board, target);
                if (board.hits.includes(target)) {
                    lastHitCoord = target;
                }
                else {
                    lastHitCoord = null;
                }
                return target;
            }
            else {
                lastHitCoord = null;
                return computerMove(board);
            }
        }
    };
    return {
        attack,
        computerMove,
        randomMove,
        availableMoves,
        lastHitCoord,
    };
}
